def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] == 2 and not seen[ny][nx]):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            components.append(cells)

    components.sort(key=lambda cells: (min(x for y, x in cells),
                                       min(y for y, x in cells)))
    out = [row[:] for row in grid]
    n = len(components)
    for i, cells in enumerate(components):
        if (n - 1 - i) % 2 == 0:
            for y, x in cells:
                out[y][x] = 8
    return out
